
import os as _os
import json as _json

def _enrich_with_hf_subprojects(modules):
    _dir = _os.path.dirname(_os.path.abspath(__file__))
    _path = _os.path.join(_dir, 'hf_subprojects.json')
    if _os.path.exists(_path):
        with open(_path, 'r', encoding='utf-8') as _f:
            _map = {item['module_number']: item for item in _json.load(_f)}
        for m in modules:
            _n = m.get('module_number')
            if _n in _map:
                if 'practice_checkpoint' not in m or not isinstance(m['practice_checkpoint'], dict):
                    m['practice_checkpoint'] = {}
                m['practice_checkpoint']['hf_subproject'] = _map[_n]
    return modules

